const { createCrossmint } = require("@crossmint/wallets-sdk");

async function signMessage() {
  const result = {
    chain: "base-sepolia",
    message: "Hello from Crossmint",
    signature: "mock-signature",
    wallet_type: "evm-smart-wallet"
  };

  try {
    // Get API key from environment
    const apiKey = process.env.CROSSMINT_API_KEY;
    if (!apiKey) {
      throw new Error("CROSSMINT_API_KEY environment variable is not set");
    }

    // Initialize Crossmint client
    const crossmint = await createCrossmint({
      apiKey: apiKey
    });

    // Create CrossmintWallets instance
    const wallets = crossmint.wallets;

    // Get or create EVM smart wallet on base-sepolia
    const wallet = await wallets.getOrCreateWallet({
      locator: "userId:demo-user-001",
      walletType: "evm-smart-wallet",
      chain: "base-sepolia",
      config: {
        recovery: {
          server: true
        }
      }
    });

    // Sign the message using the wallet
    const signature = await wallet.signMessage("Hello from Crossmint");

    // Update result with actual signature
    result.signature = signature;

    console.log("Message signed successfully!");
    console.log("Signature:", signature);
  } catch (error) {
    console.error("Error signing message:", error.message);
    result.error = error.message;
  }

  // Write result to JSON file
  const fs = require("fs");
  const path = "/home/user/sign_result.json";
  fs.writeFileSync(path, JSON.stringify(result, null, 2));
  console.log(`Result written to ${path}`);
}

signMessage();

